function ownBalanceEnvironmentWorker(string$mode,string$id,int$version,string$barrier):array
{
    $process=proc_open([...TestSupport::phpCommand(),__DIR__.'/support/balance-environments-worker.php',$mode,$id,(string)$version,$barrier],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);
