}
function ownBalanceEnvironmentAwait(callable$ready):void
{ $deadline=microtime(true)+30;while(!$ready()){if(microtime(true)>$deadline)throw new RuntimeException('Own bounded balance worker barrier timed out.');usleep(10000);} }
function ownBalanceEnvironmentFinish(array$worker):array
